import{ah as e,y as i,x as t,aE as a}from"./chunks/framework.CB1bhfrH.js";const l="/assets/image-20240328145528581.DvvXrATE.png",o="/assets/image-20240328175129136.B00zTBXM.png",r="/assets/image-20240329092527104.CfEZdCJn.png",s="/assets/image-20240329093724051.DUMSNTQN.png",n="/assets/image-20240329093931502.SEpUU6Tx.png",g="/assets/image-20240329094123182.DMjDnnf7.png",P=JSON.parse('{"title":"PicGo 图床","description":"","frontmatter":{},"headers":[],"relativePath":"public/figure/README.md","filePath":"public/figure/README.md","lastUpdated":1721962846000}'),c={name:"public/figure/README.md"},p=a('<h1 id="picgo-图床" tabindex="-1">PicGo 图床 <a class="header-anchor" href="#picgo-图床" aria-label="Permalink to &quot;PicGo 图床&quot;">​</a></h1><h3 id="图床地址" tabindex="-1">图床地址 <a class="header-anchor" href="#图床地址" aria-label="Permalink to &quot;图床地址&quot;">​</a></h3><ul><li>Gitee：<a href="https://gitee.com/kimshift/figure" target="_blank" rel="noreferrer">https://gitee.com/kimshift/figure</a></li><li>Github：<a href="https://github.com/kimshift/figure" target="_blank" rel="noreferrer">https://github.com/kimshift/figure</a></li></ul><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h3><p>利用 Gitee+PicGo+Typora+Snipaste 实现图床搭建、编写文档笔记[gitee 图床功能已废-换 github 吧]</p><h3 id="使用教程" tabindex="-1">使用教程 <a class="header-anchor" href="#使用教程" aria-label="Permalink to &quot;使用教程&quot;">​</a></h3><ol><li>安装 <ul><li>首先下载好 PicGo，下载地址：<a href="https://github.com/Molunerfinn/PicGo/releases/tag/v2.3.1" target="_blank" rel="noreferrer">https://github.com/Molunerfinn/PicGo/releases/tag/v2.3.1</a></li><li>下载并安装一个 Node.js</li><li>在 PicGo 里面搜索&quot;Gitee&quot;，下载前面那个即可。</li></ul></li></ol><p><img src="'+l+'" alt="image-20240328145528581" loading="lazy"></p><ol start="2"><li>建立 gitee（码云）图床库 <ul><li>在 Gitee 上新建一个仓库。选择【公开】仓库，勾选【使用 Readme 文件初始化这个仓库】</li><li>选择【单分支模型（只创建 master 分支）】，之后点击【创建】</li></ul></li></ol><p><img src="'+o+'" alt="image-20240328175129136" loading="lazy"></p><ol start="3"><li>配置 PicGo</li></ol><blockquote><p>注：如何获取 token：【一定要在生成 token 后将其复制到插件中，因为它仅出现一次，忘记后需要重新生成】</p><p>Gitee:头像 -&gt; 设置-&gt; 私人令牌 -&gt; 生成新令牌 -&gt; 仅勾选【projects】-&gt; 提交-&gt; 生成 token</p><p>Github:头像 -&gt; Settings-&gt; Developer settings-&gt; Personal access tokens-&gt; Generate new token -&gt; 勾选【repo】-&gt; Generate token -&gt; 生成 token</p></blockquote><p><img src="'+r+'" alt="image-20240329092527104" loading="lazy"></p><ul><li>owner：所有者，写上你的 Gitee 账号名。如果你不知道你的账号名，进入你刚才的仓库，浏览器 url 里面有。</li><li>repo：仓库名，比如我自己的仓库【figure】。</li><li>path：写上路径（可不填默认仓库根路径），这几个项都不用加“ / “符号。</li><li>token：刚才你获取的 Gitee 个人令牌 token 值。</li><li>message：不用填。</li><li>填写完成后，点击设置默认图床和确定</li></ul><h3 id="picgo-软件上传" tabindex="-1">PicGo 软件上传 <a class="header-anchor" href="#picgo-软件上传" aria-label="Permalink to &quot;PicGo 软件上传&quot;">​</a></h3><ul><li>选择任意一张图片通过剪贴板、直接拖入或选择文件等方式上传。</li><li>上传成功之后默认复制链接，可见其直接粘贴到 markdown 文档里面（也可以选择默认复制的格式，如 Markdown 格式、URL 格式、HTML 格式等）</li><li>可以 Typora + PicGo + Snipaste[截图工具]来使用。Typora 写文档，Snipaste 一键截图，PicGo 一键上传图片返回链接。</li></ul><h3 id="typora-中自动上传图片到图床" tabindex="-1">Typora 中自动上传图片到图床 <a class="header-anchor" href="#typora-中自动上传图片到图床" aria-label="Permalink to &quot;Typora 中自动上传图片到图床&quot;">​</a></h3><ul><li>进入 Typora-&gt;【偏好设置】-&gt;【插入图片时】选择【上传图片】-&gt;勾选【对本地位置的图片应用上述规则】</li><li>【上传服务设定】中的【上传服务】选择【PicGo(app)】-&gt;【PicGo 路径】PicGo 的安装路径即可-&gt;最后点击【验证图片上传选项】</li><li>出现下图的【验证成功】即可。</li></ul><p><img src="'+s+'" alt="image-20240329093724051" loading="lazy"></p><p><img src="'+n+'" alt="image-20240329093931502" loading="lazy"></p><p><img src="'+g+'" alt="image-20240329094123182" loading="lazy"></p>',21),h=[p];function u(m,d,_,f,k,b){return t(),i("div",null,h)}const T=e(c,[["render",u]]);export{P as __pageData,T as default};
